package org.cloudburstmc.protocol.bedrock.codec.v924.serializer;
import io.netty.buffer.ByteBuf; import org.cloudburstmc.protocol.bedrock.codec.BedrockCodecHelper; import org.cloudburstmc.protocol.bedrock.codec.v712.serializer.ServerboundDiagnosticsSerializer_v712; import org.cloudburstmc.protocol.bedrock.data.diagnostics.MemoryCategoryCounter; import org.cloudburstmc.protocol.bedrock.packet.ServerboundDiagnosticsPacket;
public class ServerboundDiagnosticsSerializer_v924 extends ServerboundDiagnosticsSerializer_v712 { public static final ServerboundDiagnosticsSerializer_v924 INSTANCE=new ServerboundDiagnosticsSerializer_v924(); @Override public void serialize(ByteBuf b,BedrockCodecHelper h,ServerboundDiagnosticsPacket p){super.serialize(b,h,p);h.writeArray(b,p.getMemoryCategoryValues(),(buf,x,c)->{buf.writeByte(c.getCategory().ordinal());buf.writeLongLE(c.getCurrentBytes());});}@Override public void deserialize(ByteBuf b,BedrockCodecHelper h,ServerboundDiagnosticsPacket p){super.deserialize(b,h,p);h.readArray(b,p.getMemoryCategoryValues(),(buf,x)->new MemoryCategoryCounter(MemoryCategoryCounter.Category.values()[buf.readUnsignedByte()],buf.readLongLE()));}}
